#!/usr/bin/env node
// Derive work/persian/tools/cards/cards.json from the real sources:
//   - media/briefs-local/workbench-probe/compositions.log  -> id, fps, width, height, durationFrames, durationSec
//   - work/persian/src/workbench/src/cards/demo-index.ts   -> id -> demo tsx mapping (generated by gen-index.mjs)
//   - work/persian/src/demos/<cat>/<dir>/<File>.tsx        -> source path, persianText, persianReady, background hints
// Nothing here is invented: every field is extracted or rule-derived (rules documented in the report).
import { readFileSync, writeFileSync, existsSync, readdirSync, statSync, mkdirSync, copyFileSync } from "node:fs";
import { dirname, join, resolve, relative } from "node:path";
import { fileURLToPath } from "node:url";

const here = dirname(fileURLToPath(import.meta.url));
const repo = resolve(here, "../../../.."); // work/persian/tools/cards -> repo root (4 levels up)
const WB = join(repo, "work/persian/src/workbench");
const DEMOS = join(repo, "work/persian/src/demos");
const PROBE = join(repo, "media/briefs-local/workbench-probe/compositions.log");

// ---------- 1. compositions.log ----------
const log = readFileSync(PROBE, "utf8");
const rows = [];
for (const line of log.split(/\r?\n/)) {
  const m = /^(\S+)\s+(\d+)\s+(\d+)x(\d+)\s+(\d+)\s+\(([\d.]+) sec\)\s*$/.exec(line);
  if (!m) continue;
  rows.push({
    id: m[1],
    fps: Number(m[2]),
    width: Number(m[3]),
    height: Number(m[4]),
    durationFrames: Number(m[5]),
    durationSec: Number(m[6]),
  });
}
if (!rows.length) throw new Error("compositions.log produced no rows");

// ---------- 2. demo-index.ts : demo-Stem -> @demos/<rel> ----------
const idxPath = join(WB, "src/cards/demo-index.ts");
const idx = readFileSync(idxPath, "utf8");
const relByStem = new Map();
for (const m of idx.matchAll(/import \{ (\w+) as c\d+[^}]*\} from "@demos\/([^"]+)"/g)) {
  relByStem.set(m[1], m[2]); // stem -> "camera/CrashZoom/CrashZoomReal"
}

// ---------- 3. Persian string / background extraction ----------
const FA = /[\u0600-\u06FF]/;
const FA_RE = /(["'`])((?:\\.|(?!\1)[^\\])*)\1/g;
const BG_HINT = /(?:background|backgroundColor|bgcolor|bgColor|fill|surface)\s*:\s*(["'`])([^"'`]+)\1|backgroundColor\s*=\s*(["'`])([^"'`]+)\3|(#[0-9a-fA-F]{3,8})\b/g;

function classifyStyle(text) {
  // Rule (documented in report): look for gradient first, then for the darkest / lightest background literal.
  const hexes = [];
  for (const m of text.matchAll(BG_HINT)) {
    const v = (m[2] ?? m[4] ?? m[5] ?? "").trim();
    if (v.startsWith("#")) hexes.push(v);
    else if (/^(rgb|hsl)a?\(/i.test(v)) hexes.push(v);
    else if (v) hexes.push(v);
  }
  const hasGradient = /linearGradient|radialGradient|background(Image)?\s*:\s*`?[^`]*gradient|backgroundImage.*gradient/i.test(text);
  const lum = (v) => {
    const h = /^#([0-9a-f]{3,8})$/i.exec(v);
    if (!h) return null;
    const s = h[1];
    const g = (i) => parseInt(s.slice(i, i + 2).padEnd(2, "0"), 16);
    if (s.length === 3 || s.length === 4) {
      const r = parseInt(s[0] + s[0], 16), gg = parseInt(s[1] + s[1], 16), b = parseInt(s[2] + s[2], 16);
      return (0.299 * r + 0.587 * gg + 0.114 * b) / 255;
    }
    return (0.299 * g(0) + 0.587 * g(2) + 0.114 * g(4)) / 255;
  };
  const known = hexes.map((v) => ({ v, l: lum(v) })).filter((x) => x.l !== null);
  const named = hexes.filter((v) => !/^#/.test(v)).map((v) => v.toLowerCase());
  const darkNamed = ["#000", "#000000", "black", "#111", "#111827", "#0a0a0a", "#0b0b0f", "#09090b", "#16161c", "#101014"];
  if (hasGradient && (known.length || named.length)) return { visualStyle: "gradient", how: "source-gradient+bg", hints: hexes.slice(0, 6) };
  if (hasGradient) return { visualStyle: "gradient", how: "source-gradient", hints: hexes.slice(0, 6) };
  if (known.length) {
    const darkest = known.reduce((a, b) => (b.l < a.l ? b : a));
    const lightest = known.reduce((a, b) => (b.l > a.l ? b : a));
    if (darkest.l <= 0.2) return { visualStyle: "dark", how: "source-bg-hex", hints: hexes.slice(0, 6) };
    if (lightest.l >= 0.85) return { visualStyle: "light", how: "source-bg-hex", hints: hexes.slice(0, 6) };
    return { visualStyle: "neutral", how: "source-bg-hex", hints: hexes.slice(0, 6) };
  }
  if (named.some((n) => darkNamed.includes(n))) return { visualStyle: "dark", how: "source-bg-named", hints: hexes.slice(0, 6) };
  if (named.some((n) => ["white", "#fff", "#ffffff", "paper", "ivory"].includes(n))) return { visualStyle: "light", how: "source-bg-named", hints: hexes.slice(0, 6) };
  return { visualStyle: "neutral", how: "source-default", hints: [] };
}

const out = [];
let posterHits = 0;
for (const row of rows) {
  const isDemo = row.id.startsWith("demo-");
  const stem = isDemo ? row.id.slice(5) : null;
  let rel = null;
  let category = null;
  if (isDemo && relByStem.has(stem)) {
    const r = relByStem.get(stem); // e.g. "camera/CrashZoom/CrashZoomReal"
    rel = `work/persian/src/demos/${r}.tsx`;
    category = r.split("/")[0];
  }
  if (!rel) {
    // native / background lane: locate by scanning demos tree for a matching export (cheap fallback)
    const guess = join(DEMOS, `${stem}.tsx`);
    if (existsSync(guess)) { rel = `work/persian/src/demos/${stem}.tsx`; category = "native"; }
  }
  if (isDemo && !category) category = "unknown";
  if (!isDemo && !category) {
    if (row.id.startsWith("bg-")) category = "background";
    else if (row.id === "Main") category = "native";
    else category = "native";
  }
  const srcAbs = rel ? join(repo, rel) : null;
  const text = srcAbs && existsSync(srcAbs) ? readFileSync(srcAbs, "utf8") : "";

  // Persian strings: string literals containing U+0600-U+06FF, with the surrounding JSX punctuation
  // trimmed away (e.g. `}}>درآمد ماهانه</div>` -> `درآمد ماهانه`).
  const persianText = [];
  if (text) {
    for (const m of text.matchAll(FA_RE)) {
      const raw = m[2];
      if (!FA.test(raw) || !raw.trim()) continue;
      const cleaned = raw
        .replace(/^[^\u0600-\u06FF]+(?=[\u0600-\u06FF])/, "") // drop leading JSX junk before the first Persian char
        .split(/\n/)[0] // only the first physical line: JSX/JS after the literal never sits on the same line
        .replace(/[\u0600-\u06FF](?![\u0600-\u06FF\s'«»]).*$/, (s) => s.slice(0, 1)) // drop trailing JSX junk
        .replace(/[«»،؛؟]+$/g, "")
        .trim();
      if (cleaned && FA.test(cleaned) && cleaned.length > 1) persianText.push(cleaned);
    }
  }
  const kit = /from\s+["'].*_fa|@fa\//.test(text);
  const persianReady = persianText.length > 0 || kit;

  const style = srcAbs && existsSync(srcAbs)
    ? classifyStyle(text)
    : { visualStyle: isDemo ? "neutral" : "neutral", how: "no-source", hints: [] };

  out.push({
    id: row.id,
    category,
    source: rel ?? "",
    durationFrames: row.durationFrames,
    durationSec: row.durationSec,
    fps: row.fps,
    width: row.width,
    height: row.height,
    visualStyle: style.visualStyle,
    visualStyleMethod: style.how,
    visualStyleHints: style.hints,
    persianText,
    whatItDoes: "", // filled in step 2 (needs the TSX body; kept separate so this script stays pure-extraction)
    beats: "",
    persianReady,
    transitionOverlapFrames: 0,
  });
}

mkdirSync(here, { recursive: true });
writeFileSync(join(here, "cards.extract.json"), JSON.stringify(out, null, 2));
console.log(`extracted ${out.length} cards -> cards.extract.json`);
console.log(`  demos: ${out.filter((c) => c.id.startsWith("demo-")).length}, native/background: ${out.filter((c) => !c.id.startsWith("demo-")).length}`);
console.log(`  persianReady: ${out.filter((c) => c.persianReady).length}`);
console.log(`  visualStyle: ${JSON.stringify(out.reduce((a, c) => ((a[c.visualStyle] = (a[c.visualStyle] || 0) + 1), a), {}))}`);
console.log(`  method: ${JSON.stringify(out.reduce((a, c) => ((a[c.visualStyleMethod] = (a[c.visualStyleMethod] || 0) + 1), a), {}))}`);
